"""Streamlit entry point, page 1 (Ask). Pages 2-3 live in pages/."""

import re

import streamlit as st
import streamlit.components.v1 as components

import client
from graphview import subgraph_html

st.set_page_config(page_title="AI-ecosystem KG · Ask", layout="wide")
st.title("Ask the knowledge graph")
st.caption("GraphRAG over the AI-ecosystem knowledge graph. A: vector RAG · B: graph + chunks · C: Text2Cypher. "
           "Answers are generated by gemini-3.5-flash-lite; cached questions answer instantly.")

EXAMPLES = ["Who developed Claude?", "Which companies were acquired by the developer of Claude?",
            "Which organization developed the most AI models?", "What is Constitutional AI?"]
# shareable links: ?q=<question>&s=A|B|C&kg=raw|resolved runs the question on load
qp = st.query_params
link_q = qp.get("q", "")
link_s = qp.get("s", "B").upper() if qp.get("s", "B").upper() in ("A", "B", "C") else "B"
link_kg = qp.get("kg", "resolved") if qp.get("kg") in ("raw", "resolved") else "resolved"
c1, c2, c3 = st.columns([6, 2, 2])
question = c1.text_input("Question", value=link_q or st.session_state.get("q", EXAMPLES[0]), max_chars=500)
strategy = c2.radio("Strategy", ["A", "B", "C"], index="ABC".index(link_s), horizontal=True,
                    help="A vector RAG · B GraphRAG hybrid · C Text2Cypher")
kg = c3.selectbox("Graph version", ["resolved", "raw"], index=["resolved", "raw"].index(link_kg))
st.caption("Examples: " + " · ".join(EXAMPLES))

auto = bool(link_q) and st.session_state.get("auto_done") != (link_q, link_s, link_kg)
if auto:
    st.session_state["auto_done"] = (link_q, link_s, link_kg)
if (st.button("Ask", type="primary") or auto) and question.strip():
    with st.spinner("Retrieving and generating…"):
        try:
            st.session_state["out"] = client.ask(question.strip(), strategy, kg)
            st.session_state["q"] = question
        except Exception as e:
            st.session_state.pop("out", None)
            st.error(f"API error {client.error_text(e)}")

out = st.session_state.get("out")
if out:
    st.subheader("Answer")
    st.write(out["answer"])
    m = st.columns(5)
    m[0].metric("Latency", f"{out.get('latency_s', 0):.2f} s")
    m[1].metric("LLM calls", out.get("llm_calls", 0))
    m[2].metric("Cache hits", out.get("cache_hits", 0))
    m[3].metric("Tokens in / out", f"{out.get('tokens_in', 0)} / {out.get('tokens_out', 0)}")
    m[4].metric("Strategy · graph", f"{out['strategy']} · {out['kg_version']}")
    if out.get("cypher"):
        with st.expander("Generated Cypher (read-only, safety-filtered)"):
            st.code(out["cypher"], language="cypher")
    left, right = st.columns([5, 4])
    with left:
        st.subheader(f"Sources ({len(out.get('sources') or [])})")
        for s in out.get("sources") or []:
            tag = "" if s.get("cited", True) else " · supporting, not cited"
            title = s.get("title") or s.get("doc_id")
            st.markdown(f"**[{s.get('short_id', '')}]** [{title}]({s.get('url')}){tag}" if s.get("url")
                        else f"**[{s.get('short_id', '')}]** {title}{tag}")
            if s.get("evidence_text"):
                st.caption("“" + " ".join(s["evidence_text"].split())[:400] + "”")
        if out.get("invalid_citations"):
            st.warning(f"Citations removed (not in the context): {out['invalid_citations']}")
    with right:
        st.subheader("Subgraph")
        linked = [e["name"] for e in out.get("entities_used") or []]
        guess = linked[0] if linked else next(iter(re.findall(r"\b[A-Z][\w.\-]+(?: [A-Z][\w.\-]+)*", out["question"])[1:]
                                                   or re.findall(r"\b[A-Z][\w.\-]+", out["question"])), "")
        entity = st.text_input("Entity", value=guess, help="Entity at the centre of the view")
        if entity:
            try:
                g = client.get("/graph/neighbours", entity=entity, kg_version=out["kg_version"], limit=15)
                components.html(subgraph_html(g), height=420)
                edges = g["edges"]
                if edges:
                    labels = [f"{g['center']['name'] if e['source'] == g['center']['id'] else e['name']} "
                              f"-{e['relation']}-> {e['name'] if e['source'] == g['center']['id'] else g['center']['name']}"
                              for e in edges]
                    pick = st.selectbox("Edge provenance", range(len(edges)), format_func=lambda i: labels[i])
                    prov = client.get(f"/provenance/{edges[pick]['edge_id']}", kg_version=out["kg_version"])
                    for p in prov["mentions"][:3]:
                        st.markdown(f"- “{' '.join((p['evidence'] or '').split())[:300]}” — [{p['document']}]({p['url']})")
            except Exception as e:
                st.info(f"No subgraph: {client.error_text(e)}")
